import { Router, Response } from 'express';
import { z } from 'zod';
import { announcements, assessmentAttempts, certificates, competencies, courses, enrollments, feedback, interventions, learners, notifications, organization, resources, roleRequirements, skillGaps, trainerAssessments, trainerMatches, traineeProgress, users, diagnosticQuestionBank, traineeProfiles, trainingRequests, trainerProfiles } from '../data.js';
import { auth, issueToken, publicUser, role, AuthedRequest } from '../middleware/auth.js';
import { certificateEligible, competency, gap, priority, trainerMatch } from '../services/engine.js';

const r=Router();
const ok=(res:Response,data:unknown)=>res.json({success:true,data});
const fail=(res:Response,status:number,code:string,message:string)=>res.status(status).json({success:false,error:{code,message}});
const userSchema=z.object({name:z.string().trim().min(2).max(80),email:z.string().trim().email().max(160),password:z.string().min(8).max(100),role:z.enum(['trainee','trainer']),jobRole:z.string().trim().min(2).max(100).optional(),department:z.string().trim().min(2).max(120).optional(),qualification:z.string().max(160).optional(),experience:z.string().max(160).optional(),skills:z.string().max(1000).optional(),interests:z.string().max(1000).optional(),certificates:z.string().max(1000).optional(),organization:z.string().max(160).optional()});

r.get('/health',(_,res)=>ok(res,{status:'ok',service:'capacity-connect-api',version:'v1',organization:organization.name}));

r.post('/auth/signin',(req,res)=>{
  const p=z.object({email:z.string().email(),password:z.string().min(1)}).safeParse(req.body);
  if(!p.success)return fail(res,400,'VALIDATION_ERROR','Enter a valid email and password.');
  const u=users.find(x=>x.email.toLowerCase()===p.data.email.toLowerCase()&&x.password===p.data.password);
  if(!u)return fail(res,401,'AUTH_INVALID_CREDENTIALS','The email or password is incorrect.');
  if(u.status==='pending')return fail(res,403,'AUTH_ACCOUNT_PENDING','Your account is waiting for administrator approval.');
  if(u.status==='rejected')return fail(res,403,'AUTH_ACCOUNT_REJECTED','Your account was not approved. Please contact your administrator.');
  const token=issueToken(u); ok(res,{user:publicUser(u),token});
});

r.post('/auth/signup',(req,res)=>{
  const p=userSchema.safeParse(req.body);
  if(!p.success)return fail(res,400,'VALIDATION_ERROR','Please check your account details.');
  if(users.some(u=>u.email.toLowerCase()===p.data.email.toLowerCase()))return fail(res,409,'DUPLICATE_ACCOUNT','An account with this email already exists.');
  const id=`u${Date.now()}`;
  const isTrainee=p.data.role==='trainee';
  const status='pending';
  const u:any={id,name:p.data.name,email:p.data.email,password:p.data.password,role:p.data.role,status,organizationId:organization.id,department:p.data.department||'Not set',jobRole:p.data.jobRole||(isTrainee?'Trainee':'Trainer'),onboardingComplete:false,approvalRequired:true};
  if(isTrainee){u.diagnosticComplete=false;u.diagnosticTestStatus='not_started';}
  users.push(u);
  if(isTrainee){
    traineeProfiles[u.id]={qualification:'',experience:'',skills:[],interests:[],certificates:[],organization:organization.name};
    const token=issueToken(u);
    ok(res,{message:'Account created. Complete your trainee profile, then request administrator approval.',user:publicUser(u),status:'pending',diagnosticTestStatus:'not_started',token});
    return;
  }
  const token=issueToken(u);
  ok(res,{message:'Account created. Continue to trainer onboarding.',user:publicUser(u),token});
});
r.post('/auth/signout',auth,(_,res)=>ok(res,{signedOut:true}));
r.get('/search',auth,(req:AuthedRequest,res)=>{const q=String(req.query.q||'').trim().toLowerCase();if(q.length<2)return ok(res,{results:[]});const out:{label:string;path:string}[]=[];const add=(label:string,path:string)=>{if(!out.some(x=>x.path===path))out.push({label,path})};if(req.user!.role==='trainer'){learners.filter(l=>[l.name,l.skill,l.status].some(v=>String(v).toLowerCase().includes(q))).slice(0,4).forEach(l=>add(`${l.name} · ${l.skill}`,`/trainer/learners/${l.id}`));courses.filter(c=>c.trainerId===req.user!.id&&[c.title,c.description,c.status].some(v=>String(v).toLowerCase().includes(q))).slice(0,3).forEach(c=>add(c.title,'/trainer/courses'));resources.filter(r=>r.ownerId===req.user!.id&&[r.title,r.type,r.competency,r.status].some(v=>String(v).toLowerCase().includes(q))).slice(0,3).forEach(r=>add(r.title,'/trainer/resources'));trainerAssessments.filter(a=>a.ownerId===req.user!.id&&[a.title,a.status,a.competency].some(v=>String(v).toLowerCase().includes(q))).slice(0,3).forEach(a=>add(a.title,'/trainer/assessments'));}else if(req.user!.role==='trainee'){courses.filter(c=>c.status==='Published'&&[c.title,c.description,...c.competencies].some(v=>String(v).toLowerCase().includes(q))).slice(0,4).forEach(c=>add(c.title,`/courses/${c.id}`));trainerAssessments.filter(a=>a.status==='Open'&&enrollments.some(e=>e.courseId===a.courseId&&e.traineeId===req.user!.id)&&[a.title,a.competency].some(v=>String(v).toLowerCase().includes(q))).slice(0,3).forEach(a=>add(a.title,'/trainee/assessments'));}else{users.filter(u=>u.role!=='admin'&&u.status!=='pending'&&[u.name,u.email,u.role,u.status].some(v=>String(v).toLowerCase().includes(q))).slice(0,4).forEach(u=>add(u.name,'/admin/users'));courses.filter(c=>[c.title,c.status,c.trainer].some(v=>String(v).toLowerCase().includes(q))).slice(0,3).forEach(c=>add(c.title,'/admin/courses'));trainerAssessments.filter(a=>[a.title,a.status].some(v=>String(v).toLowerCase().includes(q))).slice(0,3).forEach(a=>add(a.title,'/admin/assessments'));}ok(res,{results:out.slice(0,8)});});
r.get('/auth/me',auth,(req:AuthedRequest,res)=>ok(res,{user:publicUser(req.user!)}));

function roleRequirementsFor(roleName:string){return roleRequirements.filter((r:any)=>r.role.toLowerCase()===roleName.toLowerCase());}
function hasApprovedTrainerAccess(traineeId:string,trainerId:string){return trainingRequests.some((x:any)=>x.traineeId===traineeId&&x.trainerId===trainerId&&x.status==='Approved');}
function presentedDiagnostic(q:any,i:number){const shift=i%4;const options=q.options.map((_:any,j:number)=>q.options[(j+shift)%q.options.length]);return {id:q.id,skill:q.skill,text:q.text,options,correct:(q.correct-shift+q.options.length)%q.options.length};}
function traineeSkillSnapshot(userId:string){const user=users.find(u=>u.id===userId);const roleName=user?.jobRole||'Weather Analyst';const reqs=roleRequirementsFor(roleName);const state:any=traineeProgress[userId]||{competency:55,previous:55,diagnostic:55,competencies:{}};const competenciesMap=state.competencies||{};return {roleName,requirements:reqs.map((r:any)=>{const current=Number(competenciesMap[r.competency]??state.competency??55);const g=Math.max(0,r.required-current);const course=courses.find((c:any)=>c.status==='Published'&&c.competencies?.includes(r.competency));return {...r,current,required:r.required,gap:g,priority:g>=15||r.importance==='High'?'High':g>0?'Moderate':'On target',level:current>=90?'Expert':current>=80?'Advanced':current>=65?'Proficient':current>=50?'Working':'Awareness',course:course?.title||null,courseId:course?.id||null,reason:course?`This course directly covers the ${r.competency} skills below your role target.`:`Build focused practice for ${r.competency}.`};})};}
function buildRoadmap(userId:string){const snap=traineeSkillSnapshot(userId);const gaps=snap.requirements.filter((g:any)=>g.gap>0).sort((a:any,b:any)=>b.gap-a.gap);const steps=gaps.map((g:any,index:number)=>{const course=courses.find((c:any)=>c.status==='Published'&&c.competencies?.includes(g.competency));const trainers=users.filter((u:any)=>u.role==='trainer'&&['active'].includes(u.status as string)).map((u:any)=>{const match=trainerMatches.find((m:any)=>m.id===u.id);const expertise=match?.expertise||u.jobRole;const score=(String(expertise).toLowerCase().includes(String(g.competency).toLowerCase())?95:75);const profile=u.id==='u2'?{qualifications:'Ph.D. Meteorology',experience:'12 years',certifications:['IMD Advanced Training Certification'],performance:91,courses:'Data Processing Fundamentals, Operational Communication'}:u.id==='u6'?{qualifications:'Ph.D. Remote Sensing',experience:'10 years',certifications:['Advanced Satellite Meteorology Certification'],performance:89,courses:'Satellite Meteorology — Advanced, Forecast Interpretation'}:{qualifications:'M.Sc. Climate Science',experience:'8 years',certifications:['Climate Services Training Certification'],performance:86,courses:'Climate and Forecast Applications'};return {id:u.id,name:u.name,score,expertise,reason:match?.reason||`Strong alignment with ${g.competency} training needs.`,department:u.department,jobRole:u.jobRole,...profile};}).sort((a:any,b:any)=>b.score-a.score);return {step:index+1,competency:g.competency,current:g.current,required:g.required,gap:g.gap,priority:g.priority,action:course?`Take ${course.title}`:'Build targeted practice',courseId:course?.id||null,course:course?.title||null,trainer:trainers[0]||null,reason:course?`This learning directly covers the ${g.competency} skills below your role target.`:`Build focused practice for ${g.competency} before reassessment.`};});return {role:snap.roleName,gaps,steps,trainers:[...new Map(steps.filter((x:any)=>x.trainer).map((x:any)=>[x.trainer.id,x.trainer])).values()].slice(0,3)};}

r.get('/trainer/onboarding',auth,role('trainer'),(req:AuthedRequest,res)=>{const p=trainerProfiles[req.user!.id]||{};ok(res,{user:publicUser(req.user!),profile:p});});
r.post('/trainer/onboarding/complete',auth,role('trainer'),(req:AuthedRequest,res)=>{
  const p=z.object({organization:z.string().min(2),department:z.string().trim().min(2),jobRole:z.string().trim().min(2),qualification:z.string().trim().min(2).max(180),experience:z.string().trim().min(2).max(80),expertise:z.string().trim().min(2).max(600),certifications:z.string().max(600).optional().default(''),bio:z.string().max(600).optional().default('')}).safeParse(req.body);
  if(!p.success)return fail(res,400,'VALIDATION_ERROR','Please complete all required trainer profile details.');
  const u=req.user!;u.department=p.data.department;u.jobRole=p.data.jobRole;u.onboardingComplete=true;u.approvalRequired=true;u.status='pending';
  trainerProfiles[u.id]={...p.data,expertise:p.data.expertise.split(',').map(x=>x.trim()).filter(Boolean),certifications:p.data.certifications.split(',').map(x=>x.trim()).filter(Boolean)};
  ok(res,{user:publicUser(u),message:'Trainer profile saved. Your approval request is ready for administrator review.'});
});
r.post('/trainer/request-approval',auth,role('trainer'),(req:AuthedRequest,res)=>{if(!req.user!.onboardingComplete)return fail(res,409,'PROFILE_REQUIRED','Complete your trainer profile first.');req.user!.approvalRequired=true;req.user!.status='pending';ok(res,{status:'pending',message:'Trainer approval requested.'});});

r.post('/trainee/onboarding/complete',auth,role('trainee'),(req:AuthedRequest,res)=>{
  const p=z.object({jobRole:z.string().trim().min(2).max(100),department:z.string().trim().min(2).max(120),qualification:z.string().max(160).optional().default(''),experience:z.string().max(160).optional().default(''),skills:z.string().max(1000).optional().default(''),interests:z.string().max(1000).optional().default(''),certificates:z.string().max(1000).optional().default('')}).safeParse(req.body);
  if(!p.success)return fail(res,400,'VALIDATION_ERROR','Please complete the required onboarding details.');
  const u=req.user!;
  if(u.status!=='pending')return fail(res,409,'PROFILE_LOCKED','Your trainee application is no longer in the onboarding stage.');
  u.jobRole=p.data.jobRole;u.department=p.data.department;u.onboardingComplete=true;u.diagnosticComplete=false;u.diagnosticTestStatus='not_started';u.approvalRequired=true;u.status='pending';
  traineeProfiles[u.id]={qualification:p.data.qualification,experience:p.data.experience,skills:p.data.skills.split(',').map(x=>x.trim()).filter(Boolean),interests:p.data.interests.split(',').map(x=>x.trim()).filter(Boolean),certificates:p.data.certificates.split(',').map(x=>x.trim()).filter(Boolean),organization:organization.name};
  ok(res,{user:publicUser(u),message:'Profile saved. Request administrator approval to continue.'});
});
r.post('/trainee/request-approval',auth,role('trainee'),(req:AuthedRequest,res)=>{
  const u=req.user!;
  if(!u.onboardingComplete)return fail(res,409,'PROFILE_REQUIRED','Complete your trainee profile first.');
  u.approvalRequired=true;u.status='pending';u.diagnosticComplete=false;u.diagnosticTestStatus='not_started';
  ok(res,{status:'pending',message:'Trainee approval requested. An administrator can now review your complete profile.'});
});
r.get('/trainee/profile',auth,role('trainee'),(req:AuthedRequest,res)=>{const u=req.user!;const p=traineeProfiles[u.id]||{qualification:'',experience:'',skills:[],interests:[],certificates:[]};ok(res,{user:publicUser(u),qualifications:p.qualification?[p.qualification]:[],experience:p.experience?[{title:u.jobRole,years:parseFloat(String(p.experience))||0}]:[],skills:p.skills||[],interests:p.interests||[],certificates:(p.certificates||[]).map((x:string,i:number)=>({course:x,issued:'Prior learning',certificateId:`PRIOR-${i+1}`}))});});
