r.get('/trainee/dashboard',auth,role('trainee'),(req:AuthedRequest,res)=>{if(req.user!.status==='pending'||req.user!.approvalRequired)return fail(res,403,'APPROVAL_REQUIRED','Your account must be approved before dashboard access.');if(!req.user!.onboardingComplete)return fail(res,409,'ONBOARDING_INCOMPLETE','Complete onboarding before opening your dashboard.');const state:any=traineeProgress[req.user!.id]||{};const snap=traineeSkillSnapshot(req.user!.id);const gaps=snap.requirements;const avg=gaps.length?Math.round(gaps.reduce((a:number,g:any)=>a+g.current,0)/gaps.length):Number((traineeProgress[req.user!.id] as any)?.competency||55);const roadmap=buildRoadmap(req.user!.id);const assessments=trainerAssessments.filter(a=>a.status==='Open'&&enrollments.some(e=>e.courseId===a.courseId&&e.traineeId===req.user!.id)).map(a=>({id:a.id,title:a.title,date:a.deadline,progress:0,trainer:users.find(u=>u.id===a.ownerId)?.name||'Trainer'}));const active=courses.filter(c=>c.status==='Published').map(c=>{const e=enrollments.find(e=>e.courseId===c.id&&e.traineeId===req.user!.id);return e?{...c,progress:e.progress}:null}).filter(Boolean).filter((c:any)=>c.progress>0&&c.progress<100);const topGap=roadmap.steps[0]||null;const diagnosticComplete=state.diagnostic!==undefined&&state.diagnostic!==null;const required=gaps.length?Math.max(...gaps.map((g:any)=>g.required)):80;const safeNext=topGap||{action:'Your diagnostic is complete. Explore your learning roadmap.',courseId:null,competency:null,current:avg,required,gap:0};ok(res,{competency:avg,required,role:snap.roleName,diagnosticComplete,skillGaps:diagnosticComplete?gaps:[],recommendations:diagnosticComplete?roadmap.steps.slice(0,3):[],roadmap,activeCourses:active,nextStep:diagnosticComplete?safeNext:{action:'Complete your role-based diagnostic',courseId:null,competency:null,current:avg,required,gap:0},upcomingAssessments:assessments.slice(0,4),feedback:[{from:'Trainer team',text:'Your next steps are based on the evidence from your diagnostic and learning.'}],certificates:certificates.filter(c=>c.holderId===req.user?.id),notifications:notifications.filter(n=>n.userId===req.user?.id)});});
r.get('/trainee/competencies',auth,role('trainee'),(req:AuthedRequest,res)=>ok(res,{role:traineeSkillSnapshot(req.user!.id).roleName,competencies:traineeSkillSnapshot(req.user!.id).requirements}));
