r.get('/trainee/assessments',auth,role('trainee'),(req:AuthedRequest,res)=>{const eligibleCourseIds=new Set(enrollments.filter(e=>e.traineeId===req.user!.id).map(e=>e.courseId));const approvedTrainerIds=new Set(trainingRequests.filter((x:any)=>x.traineeId===req.user!.id&&x.status==='Approved').map((x:any)=>x.trainerId));const eligibleByTrainer=(a:any)=>approvedTrainerIds.has(a.ownerId);const list=trainerAssessments.filter(a=>a.status==='Open'&&(eligibleCourseIds.has(a.courseId)||eligibleByTrainer(a))).map(a=>{const attempts=assessmentAttempts.filter(x=>x.assessmentId===a.id&&x.traineeId===req.user!.id&&x.status==='Evaluated');const latest=attempts.at(-1);const locked=Boolean(latest)&&(Number(latest.score)>=a.passingScore||attempts.length>=a.attemptLimit);return {id:a.id,title:a.title,course:courses.find(c=>c.id===a.courseId)?.title||'Course',trainer:users.find(u=>u.id===a.ownerId)?.name||'Trainer',status:locked?'Result Available':'Open',deadline:a.deadline,score:latest?.score??null,attemptsUsed:attempts.length,questions:a.questions.length,timeLimitMinutes:a.timeLimitMinutes,passingScore:a.passingScore,attemptLimit:a.attemptLimit,eligible:true};});const resultOnly=trainerAssessments.filter(a=>eligibleCourseIds.has(a.courseId)&&assessmentAttempts.some(x=>x.assessmentId===a.id&&x.traineeId===req.user!.id&&x.status==='Evaluated')&&!list.some(x=>x.id===a.id)).map(a=>{const latest=assessmentAttempts.filter(x=>x.assessmentId===a.id&&x.traineeId===req.user!.id&&x.status==='Evaluated').at(-1);return {id:a.id,title:a.title,course:courses.find(c=>c.id===a.courseId)?.title||'Course',trainer:users.find(u=>u.id===a.ownerId)?.name||'Trainer',status:'Result Available',deadline:a.deadline,score:latest?.score??null,attemptsUsed:1,questions:a.questions.length,timeLimitMinutes:a.timeLimitMinutes,passingScore:a.passingScore,attemptLimit:a.attemptLimit,eligible:true};});ok(res,{assessments:[...list,...resultOnly]});});
