r.get('/diagnostic',auth,role('trainee'),(req:AuthedRequest,res)=>{if(req.user!.status!=='active')return fail(res,403,'APPROVAL_REQUIRED','Your account must be approved before starting the diagnostic.');if(!req.user!.onboardingComplete)return fail(res,409,'ONBOARDING_REQUIRED','Complete your profile first.');if(req.user!.diagnosticTestStatus==='completed'||traineeProgress[req.user!.id]?.diagnosticComplete)return fail(res,409,'DIAGNOSTIC_ALREADY_COMPLETED','Your diagnostic is already complete.');const questions=diagnosticQuestionBank[req.user!.jobRole]||diagnosticQuestionBank['Weather Analyst'];const reqs=roleRequirementsFor(req.user!.jobRole);ok(res,{title:`${req.user!.jobRole} Diagnostic`,role:req.user!.jobRole,questions:questions.map((q:any,i:number)=>{const p=presentedDiagnostic(q,i);return {id:p.id,skill:p.skill,text:p.text,options:p.options}}),competencies:reqs});});
r.post('/diagnostic/submit',auth,role('trainee'),(req:AuthedRequest,res)=>{if(req.user!.status!=='active')return fail(res,403,'APPROVAL_REQUIRED','Your account must be approved before submitting the diagnostic.');if(!req.user!.onboardingComplete)return fail(res,409,'ONBOARDING_REQUIRED','Complete your profile first.');if(req.user!.diagnosticTestStatus==='completed'||traineeProgress[req.user!.id]?.diagnosticComplete)return fail(res,409,'DIAGNOSTIC_ALREADY_COMPLETED','Your diagnostic is already complete.');const questions=diagnosticQuestionBank[req.user!.jobRole]||diagnosticQuestionBank['Weather Analyst'];const answers=Array.isArray(req.body.answers)?req.body.answers:[];if(answers.length!==questions.length)return fail(res,400,'INCOMPLETE_DIAGNOSTIC','Answer every diagnostic question before continuing.');const bySkill:any={};questions.forEach((q:any,i:number)=>{const answer=answers[i];const presented=presentedDiagnostic(q,i);const correct=Number(answer?.optionIndex)===presented.correct;bySkill[q.skill]??={correct:0,total:0};bySkill[q.skill].total++;if(correct)bySkill[q.skill].correct++;});const reqs=roleRequirementsFor(req.user!.jobRole);const state:any=traineeProgress[req.user!.id]||{competency:55,previous:55,diagnostic:55,competencies:{}};state.competencies={...(state.competencies||{})};const results=reqs.map((r:any)=>{const evidence=bySkill[r.competency];const current=evidence?Math.round((evidence.correct/evidence.total)*100):55;state.competencies[r.competency]=current;return {...r,current,gap:Math.max(0,r.required-current),priority:(r.required-current)>=15||r.importance==='High'?'High':current<r.required?'Moderate':'On target',level:current>=90?'Expert':current>=80?'Advanced':current>=65?'Proficient':current>=50?'Working':'Awareness'};});const avg=results.length?Math.round(results.reduce((a:number,r:any)=>a+r.current,0)/results.length):55;state.previous=avg;state.diagnostic=avg;state.competency=avg;state.diagnosticComplete=true;req.user!.diagnosticComplete=true;req.user!.diagnosticTestStatus='completed';req.user!.approvalRequired=false;traineeProgress[req.user!.id]=state;const roadmap=buildRoadmap(req.user!.id);ok(res,{score:avg,role:req.user!.jobRole,competencies:results,gaps:roadmap.gaps,roadmap,trainers:roadmap.trainers,message:`Your ${req.user!.jobRole} baseline is ready. We mapped your gaps and built your first learning roadmap.`});});

