r.post('/assessments/:id/start',auth,role('trainee'),(req:AuthedRequest,res)=>{const a=trainerAssessments.find(x=>x.id===req.params.id&&x.status==='Open');if(!a)return fail(res,404,'ASSESSMENT_NOT_AVAILABLE','This assessment is not available.');if(!enrollments.some(e=>e.courseId===a.courseId&&e.traineeId===req.user!.id))return fail(res,403,'ASSESSMENT_NOT_ASSIGNED','Enroll in the related course before attempting this assessment.');const deadlineAt=a.deadlineAt?new Date(a.deadlineAt):null;if(deadlineAt&&!Number.isNaN(deadlineAt.getTime())&&Date.now()>deadlineAt.getTime())return fail(res,409,'ASSESSMENT_CLOSED','This assessment deadline has passed.');const prior=assessmentAttempts.filter(x=>x.assessmentId===a.id&&x.traineeId===req.user!.id);if(prior.some(x=>x.status==='In Progress'))return ok(res,{attemptId:prior.find(x=>x.status==='In Progress').id,status:'In Progress',startedAt:prior.find(x=>x.status==='In Progress').startedAt,resumed:true});if(prior.length>=a.attemptLimit)return fail(res,409,'ATTEMPT_LIMIT_REACHED','You have used all allowed attempts.');const attempt:any={id:`att${Date.now()}`,assessmentId:a.id,traineeId:req.user!.id,status:'In Progress',startedAt:new Date().toISOString()};assessmentAttempts.push(attempt);ok(res,{attemptId:attempt.id,status:attempt.status,startedAt:attempt.startedAt});});
r.post('/assessments/:id/submit',auth,role('trainee'),(req:AuthedRequest,res)=>{const a=trainerAssessments.find(x=>x.id===req.params.id&&x.status==='Open');if(!a)return fail(res,404,'ASSESSMENT_NOT_AVAILABLE','This assessment is not available.');if(!enrollments.some(e=>e.courseId===a.courseId&&e.traineeId===req.user!.id)&&!hasApprovedTrainerAccess(req.user!.id,a.ownerId))return fail(res,403,'ASSESSMENT_NOT_ASSIGNED','Enroll in the related course or get trainer approval before submitting this assessment.');const answers=Array.isArray(req.body.answers)?req.body.answers:[];if(answers.length!==a.questions.length)return fail(res,400,'INCOMPLETE_ASSESSMENT','Answer every question before submitting.');const attempt=[...assessmentAttempts].reverse().find(x=>x.assessmentId===a.id&&x.traineeId===req.user!.id&&x.status==='In Progress');if(!attempt)return fail(res,409,'ATTEMPT_NOT_STARTED','Start the assessment before submitting.');const score=Math.round(answers.reduce((sum:any,item:any)=>{const q=a.questions.find((qq:any)=>`${a.id}-q${a.questions.indexOf(qq)+1}`===item.questionId);return sum+(q&&q.options[q.correct]===q.options.find((_:any,j:number)=>String.fromCharCode(97+j)===item.optionId)?q.marks:0)},0)/a.questions.reduce((sum:any,q:any)=>sum+q.marks,0)*100);attempt.status='Evaluated';attempt.score=score;attempt.completedAt=new Date().toISOString();const pass=score>=a.passingScore;const focusAreas=a.questions.filter((q:any,i:number)=>{const item=answers.find((x:any)=>x.questionId===`${a.id}-q${i+1}`);return !item||String.fromCharCode(97+q.correct)!==item.optionId}).map((q:any)=>q.skill);const state:any=traineeProgress[req.user!.id]||{competency:63,previous:63,diagnostic:63,competencies:{}};state.competencies={...(state.competencies||{})};const old=Number(state.competencies[a.competency]??state.competency);if(pass){state.competencies[a.competency]=Math.max(old,Math.min(100,old+Math.max(3,Math.round((100-old)*0.2))));}state.previous=old;state.competency=Math.round(Object.values(state.competencies).reduce((sum:number,v:any)=>sum+Number(v),0)/Math.max(1,Object.keys(state.competencies).length));traineeProgress[req.user!.id]=state;ok(res,{attemptId:attempt.id,score,passed:pass,title:a.title,course:courses.find(c=>c.id===a.courseId)?.title||'Course',focusAreas:[...new Set(focusAreas)].slice(0,3),competencyAfter:state.competencies[a.competency],message:'Assessment submitted. Your result is ready.'});});

r.post('/assessments/:id/feedback',auth,role('trainee'),(req:AuthedRequest,res)=>{const a=trainerAssessments.find(x=>x.id===req.params.id);if(!a)return fail(res,404,'ASSESSMENT_NOT_FOUND','We could not find this assessment.');const attempt=assessmentAttempts.find(x=>x.id===req.body?.attemptId&&x.traineeId===req.user!.id&&x.assessmentId===a.id&&x.status==='Evaluated');if(!attempt)return fail(res,409,'ATTEMPT_REQUIRED','Complete the assessment before leaving feedback.');const p=z.object({rating:z.number().int().min(1).max(5),comment:z.string().max(500).optional()}).safeParse(req.body);if(!p.success)return fail(res,400,'VALIDATION_ERROR','Please provide a rating from 1 to 5.');const item={id:`f${Date.now()}`,fromUserId:req.user!.id,trainerId:a.ownerId,objectType:'assessment',objectId:a.id,attemptId:attempt.id,rating:p.data.rating,comment:p.data.comment||'',score:attempt.score,createdAt:'Just now'};feedback.push(item);ok(res,{feedback:item,message:'Your assessment feedback was sent to the trainer.'});});
r.get('/reassessments/status',auth,role('trainee'),(req:AuthedRequest,res)=>{const state:any=traineeProgress[req.user!.id]||{competency:55,previous:55,diagnostic:55,competencies:{}};const mine=interventions.filter(i=>i.learnerId===req.user!.id);const available=mine.length>0&&mine.every(i=>i.status==='Completed');const snap=traineeSkillSnapshot(req.user!.id);const target=snap.requirements.filter((g:any)=>g.gap>0).sort((a:any,b:any)=>b.gap-a.gap)[0]||snap.requirements[0];const current=target?Number(state.competencies?.[target.competency]??target.current):state.competency;ok(res,{available,competency:target?.competency||null,previous:current,required:target?.required||80,supportSteps:mine.length,completedSteps:mine.filter(i=>i.status==='Completed').length});});
r.post('/reassessments/:id/submit',auth,role('trainee'),(req:AuthedRequest,res)=>{const mine=interventions.filter(i=>i.learnerId===req.user!.id);if(!mine.length||mine.some(i=>i.status!=='Completed'))return fail(res,409,'SUPPORT_INCOMPLETE','Complete your support plan before taking the reassessment.');const state:any=traineeProgress[req.user!.id]||{competency:55,previous:55,diagnostic:55,competencies:{}};const snap=traineeSkillSnapshot(req.user!.id);const target=snap.requirements.find((g:any)=>g.competency===req.params.id)||snap.requirements.filter((g:any)=>g.gap>0).sort((a:any,b:any)=>b.gap-a.gap)[0];if(!target)return fail(res,404,'REASSESSMENT_TARGET_NOT_FOUND','There is no competency waiting for reassessment.');const previous=Number(state.competencies?.[target.competency]??target.current);const current=Math.min(target.required,previous+10);state.competencies={...(state.competencies||{}),[target.competency]:current};state.previous=previous;state.competency=Math.round(Object.values(state.competencies).reduce((sum:number,v:any)=>sum+Number(v),0)/Object.keys(state.competencies).length);traineeProgress[req.user!.id]=state;const learner=learners.find(l=>l.id===req.user!.id);if(learner){learner.current=current;learner.required=target.required;learner.progress=Math.min(100,learner.progress+8);learner.status=current>=target.required?'On Track':'Needs Support';}ok(res,{score:Math.min(100,current+3),previous,growth:current-previous,currentCompetency:current,competency:target.competency,required:target.required,certificateEligible:false,message:`Great progress. Your ${target.competency} competency increased by ${current-previous} points.`});});

