r.get('/admin/dashboard',auth,role('admin'),(_,res)=>{const trainees=users.filter(u=>u.role==='trainee');const trainers=users.filter(u=>u.role==='trainer'&&['active'].includes(u.status as string));const publishedCourses=courses.filter(c=>c.status==='Published');const issued=certificates.length;const totalEnrollments=enrollments.length;const completed=enrollments.filter(e=>e.progress>=100).length;const evaluated=assessmentAttempts.filter(a=>a.status==='Evaluated');const avgAssessment=evaluated.length?Math.round(evaluated.reduce((n:number,a:any)=>n+Number(a.score||0),0)/evaluated.length):0;const allScores=trainees.flatMap(u=>Object.values((traineeProgress[u.id] as any)?.competencies||{}).map(Number));const avgCompetency=allScores.length?Math.round(allScores.reduce((a:number,b:number)=>a+b,0)/allScores.length):0;const priorityGaps=trainees.reduce((n,u)=>n+traineeSkillSnapshot(u.id).requirements.filter((g:any)=>g.gap>=15).length,0);const compNames=[...new Set(roleRequirements.map((r:any)=>r.competency))];const competency=compNames.slice(0,4).map(name=>{const rows=trainees.flatMap(u=>traineeSkillSnapshot(u.id).requirements.filter((g:any)=>g.competency===name));return {name,value:rows.length?Math.round(rows.reduce((n:number,x:any)=>n+x.current,0)/rows.length):0,target:rows.length?Math.max(...rows.map((x:any)=>x.required)):80};});const trainingDemand=compNames.map(name=>({name,value:trainees.reduce((n,u)=>n+(traineeSkillSnapshot(u.id).requirements.some((g:any)=>g.competency===name&&g.gap>0)?1:0),0)})).filter(x=>x.value>0).sort((a,b)=>b.value-a.value).slice(0,5);ok(res,{kpis:{trainees:trainees.length,trainers:trainers.length,courses:publishedCourses.length,certificates:issued,averageCompetency:avgCompetency,priorityGaps,activeUsers:users.filter(u=>['active'].includes(u.status as string)).length,enrollments:totalEnrollments,completionRate:totalEnrollments?Math.round(completed/totalEnrollments*100):0,assessmentParticipation:trainees.length?Math.min(100,Math.round(assessmentAttempts.length/trainees.length*100)):0,averageAssessment:avgAssessment},competency,trainingDemand,recent:[{text:`${publishedCourses.length} published courses available`,time:'Now'},{text:`${trainers.length} trainers active`,time:'Now'},{text:`${issued} certificates issued`,time:'Now'}]});});
