r.get('/admin/capacity',auth,role('admin'),(_,res)=>{const roles=[...new Set(roleRequirements.map((r:any)=>r.role))];const names=[...new Set(roleRequirements.map((r:any)=>r.competency))];const heatmap=names.map(name=>[name,...roles.map(roleName=>{const rows=users.filter(u=>u.role==='trainee'&&u.jobRole===roleName).flatMap(u=>traineeSkillSnapshot(u.id).requirements.filter((g:any)=>g.competency===name));return rows.length?Math.round(rows.reduce((n:number,x:any)=>n+x.current,0)/rows.length):0;})]);const demand=names.map(name=>({name,value:users.filter(u=>u.role==='trainee').filter(u=>traineeSkillSnapshot(u.id).requirements.some((g:any)=>g.competency===name&&g.gap>0)).length})).sort((a,b)=>b.value-a.value).slice(0,5);const vals=users.filter(u=>u.role==='trainee').flatMap(u=>traineeSkillSnapshot(u.id).requirements);const coverage=vals.length?Math.round(vals.reduce((n:number,x:any)=>n+Math.min(100,x.current/x.required*100),0)/vals.length):0;ok(res,{heatmap,roles,demand,coverage,growth:10});});
