r.post('/trainee/certificates/:courseId/generate',auth,role('trainee'),(req:AuthedRequest,res)=>{const course=courses.find(c=>c.id===req.params.courseId&&c.status==='Published');if(!course)return fail(res,404,'COURSE_NOT_FOUND','We could not find this course.');const enrollment=enrollments.find(e=>e.courseId===course.id&&e.traineeId===req.user!.id);const assessment=trainerAssessments.find(x=>x.courseId===course.id&&x.status==='Open')||trainerAssessments.find(x=>x.courseId===course.id);const passed=assessment?assessmentAttempts.some(a=>a.traineeId===req.user!.id&&a.assessmentId===assessment.id&&a.status==='Evaluated'&&a.score>=assessment.passingScore):false;const state:any=traineeProgress[req.user!.id]||{competency:63,previous:63,diagnostic:55,competencies:{}};const courseCompetency=course.competencies?.[0];const current=Number(state.competencies?.[courseCompetency]??state.competency);const required=roleRequirementsFor(req.user!.jobRole).find((r:any)=>r.competency===courseCompetency)?.required||80;if(!enrollment||enrollment.progress<100||!passed||current<required)return fail(res,409,'CERTIFICATE_NOT_ELIGIBLE','Complete the course, pass its assessment and meet the required competency level first.');const existing=certificates.find(c=>c.holderId===req.user!.id&&c.course===course.title);if(existing)return ok(res,{certificate:existing,message:'Your certificate already exists.'});const certificate={id:`cert${Date.now()}`,certificateId:`CC-2026-${String(10000+certificates.length+1).padStart(5,'0')}`,holderId:req.user!.id,holder:req.user!.name,course:course.title,issued:new Date().toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}),valid:true};certificates.push(certificate);ok(res,{certificate,message:'Certificate generated successfully.'});});
